  "code": "def generated_builder(feature_cache, extra):\n    objective = feature_cache['objective']\n    mask = objective[:, :, None] < objective[:, None, :]\n    b_idx, winner_idx, loser_idx = mask.nonzero(as_tuple=True)\n    if b_idx.numel() == 0:\n        return PrefBatch(mode='pairwise', pair_idx=(b_idx, winner_idx, loser_idx), weight=None, meta={'builder': 'all_pairs', 'weight_family': 'gap_bandpass'})\n    gap = objective[b_idx, loser_idx] - objective[b_idx, winner_idx]\n    gap = torch.nan_to_num(gap, nan=0.0, posinf=0.0, neginf=0.0).clamp(min=0.0)\n    # Parameters for bandpass weighting (configurable via extra)\n    low = float(extra.get('weight_low', 0.5))\n    high = float(extra.get('weight_high', 3.0))\n    clamp_lo = 0.1\n    clamp_hi = 5.0\n    # Bandpass: weight ~ gap * (1 - (gap - center)^2 / bandwidth^2) clipped to zero outside band\n    center = (low + high) / 2.0\n    bandwidth = (high - low) / 2.0\n    # Compute bandpass raw weight\n    diff = gap - center\n    raw = gap * torch.clamp(1.0 - (diff * diff) / (bandwidth * bandwidth + 1e-8), min=0.0)\n    # Clamp weight for stability\n    weight = raw.clamp(clamp_lo, clamp_hi)\n    return PrefBatch(mode='pairwise', pair_idx=(b_idx, winner_idx, loser_idx), weight=weight, meta={'builder': 'all_pairs', 'weight_family': 'gap_bandpass'})"
